return [
  { json: { filename: "index.html" } },
  { json: { filename: "dashboard.html" } },
  { json: { filename: "cv.html" } },
];

const api = $json;
const filename = api.name || api.path;
// GitHub get returns base64-encoded content when asBinaryProperty is false
const raw = (api.content || "").replace(/\n/g, "");
let html = Buffer.from(raw, "base64").toString("utf8");

const widget = [
  '<div id="google_translate_element" style="position:fixed; top:10px; right:10px; z-index:70;"></div>',
  '<script>',
  String.fromCharCode(32,32) + "function googleTranslateElementInit() {",
  String.fromCharCode(32,32,32,32) + "new google.translate.TranslateElement({",
  String.fromCharCode(32,32,32,32,32,32) + "pageLanguage: " + String.fromCharCode(39) + "en" + String.fromCharCode(39) + ",",
  String.fromCharCode(32,32,32,32,32,32) + "includedLanguages: " + String.fromCharCode(39) + "ar,en" + String.fromCharCode(39) + ",",
  String.fromCharCode(32,32,32,32,32,32) + "layout: google.translate.TranslateElement.InlineLayout.HORIZONTAL",
  String.fromCharCode(32,32,32,32) + "}, " + String.fromCharCode(39) + "google_translate_element" + String.fromCharCode(39) + ");",
  String.fromCharCode(32,32) + "}",
  '</script>',
  '<script src="//translate.google.com/translate_a/element.js?cb=googleTranslateElementInit"></script>',
].join("\n");

let changed = false;
if (html.indexOf("google_translate_element") === -1) {
  const idx = html.lastIndexOf("</body>");
  if (idx !== -1) {
    html = html.slice(0, idx) + widget + "\n" + html.slice(idx);
  } else {
    html = html + "\n" + widget + "\n";
  }
  changed = true;
}

return { filename: filename, html: html, changed: changed };
